insert into exercises (slug, name, muscle, how, tip, works, alt_slug, image_path) values
  ('goblet_squat', 'Goblet squat', 'legs', 'Hold one dumbbell at your chest. Sit down between your heels until thighs are level, then stand.', 'Chest up, knees follow your toes.', 'Thighs and glutes. The base of leg strength.', null, '/images/exercises/goblet_squat-0.webp'),
  ('db_romanian_deadlift', 'Dumbbell Romanian deadlift', 'legs', 'Dumbbells in front of your thighs, soft knees. Push hips back, slide the weights down your legs, stand by squeezing your glutes.', 'Back flat. Stop when you feel the stretch behind your knees.', 'Hamstrings and glutes. Keep it light, it protects your lower back long term.', null, '/images/exercises/db_romanian_deadlift-0.webp'),
  ('bulgarian_split_squat', 'Bulgarian split squat', 'legs', 'Back foot on a bench, front foot a big step ahead. Lower until the back knee nearly touches, push up through the front heel.', 'Most of your weight on the front leg. Go slow.', 'Thighs, glutes, balance. Football legs.', null, '/images/exercises/bulgarian_split_squat-0.webp'),
  ('hip_thrust', 'Hip thrust', 'legs', 'Upper back on a bench, dumbbell on your hips, feet flat. Drive hips up to a straight line, pause, lower.', 'Chin tucked. Squeeze 1 second at the top.', 'Glutes. Sprint power.', null, '/images/exercises/hip_thrust-0.webp'),
  ('calf_raise', 'Calf raise', 'legs', 'Stand on a step edge, heels hanging. Rise high on your toes, lower slowly below the step.', 'Pause at the top. No bouncing.', 'Calves and ankles. Fewer ankle knocks on the pitch.', null, '/images/exercises/calf_raise-0.webp'),
  ('dead_bug', 'Dead bug', 'core', 'On your back, arms up, knees bent at 90 degrees. Lower opposite arm and leg slowly, return, switch.', 'Lower back stays pressed to the floor.', 'Deep core. Back-friendly.', null, '/images/exercises/dead_bug-0.webp'),
  ('db_bench_press', 'Dumbbell bench press', 'chest', 'Lie on a bench, dumbbells over your chest. Lower to the sides of your chest, press back up.', 'Shoulder blades pinched, elbows at about 45 degrees.', 'Chest, front shoulders, triceps.', null, '/images/exercises/db_bench_press-0.webp'),
  ('incline_db_press', 'Incline dumbbell press', 'chest', 'Bench at 30 degrees. Press dumbbells from upper chest to above your face.', 'Keep your back on the bench.', 'Upper chest and shoulders.', null, '/images/exercises/incline_db_press-0.webp'),
  ('seated_db_shoulder_press', 'Seated dumbbell shoulder press', 'shoulders', 'Sit tall, dumbbells at ear height. Press up until arms are straight, lower to your ears.', 'Ribs down. Don''t lean back.', 'Shoulders and triceps.', null, '/images/exercises/seated_db_shoulder_press-0.webp'),
  ('lateral_raise', 'Lateral raise', 'shoulders', 'Dumbbells at your sides. Raise out to shoulder height, lower slowly.', 'Light weight. Lead with your elbows, no swinging.', 'Side shoulders. Wider frame.', null, '/images/exercises/lateral_raise-0.webp'),
  ('overhead_triceps_extension', 'Overhead triceps extension', 'arms', 'Hold one dumbbell overhead with both hands. Lower behind your head, extend back up.', 'Elbows point forward and stay close.', 'Triceps, the back of the arm.', null, '/images/exercises/overhead_triceps_extension-0.webp'),
  ('plank', 'Plank', 'core', 'Forearms on the floor, body straight from head to heels. Hold.', 'Squeeze your glutes. Don''t let hips sag.', 'Whole core.', null, '/images/moves/plank.svg'),
  ('pull_up', 'Pull-up', 'back', 'Hang from the bar, palms away. Pull until your chin passes the bar, lower all the way. Can''t do one yet: jump up, lower for 5 seconds.', 'Chest to the bar. No kicking.', 'Back and biceps.', 'lat_pulldown', '/images/exercises/pull_up-0.webp'),
  ('one_arm_db_row', 'One-arm dumbbell row', 'back', 'Hand and knee on a bench, dumbbell in the other hand. Pull it to your hip, lower slowly.', 'Back flat, elbow close to your side.', 'Upper back and lats. Better posture.', 'seated_cable_row', '/images/exercises/one_arm_db_row-0.webp'),
  ('rear_delt_fly', 'Rear delt fly', 'shoulders', 'Lean forward with a flat back, light dumbbells hanging. Raise them out to the sides, squeeze, lower.', 'Light and slow.', 'Back of the shoulders. Fixes desk posture.', null, '/images/exercises/rear_delt_fly-0.webp'),
  ('db_curl', 'Dumbbell curl', 'arms', 'Dumbbells at your sides, palms forward. Curl up, lower slowly.', 'Elbows pinned to your sides.', 'Biceps.', null, '/images/exercises/db_curl-0.webp'),
  ('hammer_curl', 'Hammer curl', 'arms', 'Same as a curl with palms facing each other.', 'No swinging. 2 seconds down.', 'Biceps and forearms. Grip.', null, '/images/exercises/hammer_curl-0.webp'),
  ('side_plank', 'Side plank', 'core', 'On one forearm, feet stacked, lift your hips into a straight line. Hold, switch sides.', 'Hips high and pushed forward.', 'Side core. Protects the lower back.', null, '/images/exercises/side_plank-0.webp'),
  ('lat_pulldown', 'Lat pulldown', 'back', 'Sit with thighs under the pad, grip just wider than your shoulders. Pull the bar to your upper chest, return slowly.', 'Lead with your elbows. Don''t lean back to yank it.', 'Back and biceps. The swap when there is no pull-up bar.', null, '/images/exercises/lat_pulldown-0.webp'),
  ('seated_cable_row', 'Seated cable row', 'back', 'Sit tall, feet braced, knees soft. Pull the handle to your belly, squeeze your shoulder blades, return slowly.', 'Don''t rock your torso. Let the arms stretch fully at the front.', 'Upper back and lats. Better posture.', null, '/images/exercises/seated_cable_row-0.webp'),
  ('push_up', 'Push-up', 'chest', 'Hands under your shoulders, body straight from head to heels. Lower your chest to just above the floor, press back up.', 'Elbows about 45 degrees from your body. Don''t let hips sag.', 'Chest, front shoulders, triceps. No kit needed.', null, '/images/exercises/push_up-0.webp'),
  ('kneeling_hip_flexor_stretch', 'Kneeling hip flexor stretch', 'stretch', 'Kneel on one knee, other foot flat in front. Tuck your tailbone under and shift forward until the front of the back hip stretches.', 'Squeeze the back glute. Don''t arch your lower back.', 'Hip flexors. Opens the front of the hip that sitting shortens. The main one for lower back tightness.', 'couch_stretch', '/images/exercises/kneeling_hip_flexor_stretch-0.webp'),
  ('couch_stretch', 'Couch stretch', 'stretch', 'Back knee on the floor beside a wall, back foot up the wall behind you. Step the other foot forward and lift your torso upright.', 'Squeeze the back glute. Ease in, don''t force it.', 'Front of the hip and thigh. The harder step up from the kneeling stretch.', null, '/images/moves/couch_stretch.svg'),
  ('hip_90_90', '90/90 hip switch', 'stretch', 'Sit with both knees bent at 90 degrees, one shin in front and one to the side. Rotate your knees over to switch sides.', 'Sit tall. Move slowly, inside a range that feels easy.', 'Hip rotation for football.', null, '/images/moves/hip_90_90.svg'),
  ('cat_cow', 'Cat-cow', 'stretch', 'On hands and knees, round your back up toward the ceiling, then drop your belly and lift your chest. Move with your breath.', 'Slow and smooth. Move the whole spine, not just the neck.', 'Lower back and spine. Moves the lower back gently.', null, '/images/moves/cat_cow.svg'),
  ('lying_hamstring_stretch', 'Lying hamstring stretch', 'stretch', 'Lie on your back, loop a towel or band round one foot. Raise that leg and pull it gently toward you, other leg flat.', 'Keep the knee as straight as is comfortable. No bouncing.', 'Hamstrings. Tight hamstrings pull on the lower back.', null, '/images/moves/lying_hamstring_stretch.svg')
